from typing import Iterable, List, Tuple

def shift_weekly(entries: Iterable[Tuple[int, int, int]], offset: int) -> List[Tuple[int, int, int]]:
    result: List[Tuple[int, int, int]] = []
    week_min = 7 * 1440
    for day, start, end in entries:
        if not (0 <= day <= 6): raise ValueError(f"Day {day}")
        if not (0 <= start < 1440): raise ValueError(f"Start {start}")
        if end <= start: raise ValueError(f"End {end} <= Start {start}")
        a_start = (day * 1440 + start + offset) % week_min
        a_end = (day * 1440 + end + offset) % week_min
        if a_end <= a_start:
            _add(result, a_start, week_min)
            _add(result, 0, a_end)
        else:
            _add(result, a_start, a_end)
    result.sort()
    return result

def _add(res: List[Tuple[int, int, int]], s: int, e: int) -> None:
    cur = s
    while cur < e:
        d = cur // 1440
        st = cur % 1440
        nxt = (d + 1) * 1440
        en = min(e, nxt)
        en_min = en % 1440
        if en_min == 0: en_min = 1440
        res.append((d, st, en_min))
        cur = nxt
"}}, "messages": []}

